{
  "approve": true,
  "reason": "The contract is mathematically precise, unambiguous, and self-consistent. It clearly defines input validation (strictly positive values, non-negative weights, non-zero total weight), the exact formulas for weighted mean, population variance, standard deviation, and geometric mean, and the rounding requirement (6 decimal places). The edge cases listed in the contract align perfectly with the validation rules. No external dependencies are required, and the logic is deterministic.",
  "cases": [
    {
      "input": {
        "rows": [
          {"value": 10.0, "weight": 2.0},
          {"value": 20.0, "weight": 3.0}
        ]
      },
      "expected": {
        "weighted_mean": 16.0,
        "weighted_population_variance": 24.0,
        "weighted_population_sd": 4.898979,
        "weighted_geometric_mean": 15.848932
      }
    },
    {
      "input": {
        "rows": [
          {"value": 5.0, "weight": 1.0}
        ]
      },
      "expected": {
        "weighted_mean": 5.0,
        "weighted_population_variance": 0.0,
        "weighted_population_sd": 0.0,
        "weighted_geometric_mean": 5.0
      }
    },
    {
      "input": {
        "rows": [
          {"value": 100.0, "weight": 0.0},
          {"value": 50.0, "weight": 1.0}
        ]
      },
      "expected": {
        "weighted_mean": 50.0,
        "weighted_population_variance": 0.0,
        "weighted_population_sd": 0.0,
        "weighted_geometric_mean": 50.0
      }
    },
    {
      "input": {
        "rows": []
      },
      "expected_error": "ValueError"
    },
    {
      "input": {
        "rows": [
          {"value": "10", "weight": 2.0}
        ]
      },
      "expected_error": "ValueError"
    },
    {
      "input": {
        "rows": [
          {"value": 10.0, "weight": -1.0}
        ]
      },
      "expected_error": "ValueError"
    },
    {
      "input": {
        "rows": [
          {"value": 0.0, "weight": 1.0}
        ]
      },
      "expected_error": "ValueError"
    },
    {
      "input": {
        "rows": [
          {"value": 10.0, "weight": 0.0},
          {"value": 20.0, "weight": 0.0}
        ]
      },
      "expected_error": "ValueError"
    }
  ]
}
